head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getFusionChartData]<br/>LinkedDataList 모듈의 데이터를 FusionChart 의 JSON 데이터로 반환합니다.",
    "validation" : [
        "chartType(필수) 파라미터로 반환되는 JSON 데이터 종류를 FusionChart 의 chartType 속성값 중 하나로 설정합니다.",
        "labelNode(필수) 파라미터로 FusionChart 의 Label 데이터로 사용될 Column 의 ID 를 설정합니다.",
        "seriesColumns(필수) 파라미터로 FusionChart 의 Series 데이터로 사용될 Column 의 ID 를 배열 형식의 문자열로 설정합니다.",
        "파라미터에 만족하는 형태로 FusionChart 의 JSON 데이터를 반환합니다.",
        "chartType 파라미터값에 따라 반환되는 JSON 데이터의 형식이 달라집니다.",
        "FusionChart 컴포넌트와 바인드 되지 않아도 JSON 데이터를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };    

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);      

    // target 생성    
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strOrgTarget = '';
    // let strFusionChart = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strOrgTarget += '<w2:dataList ' + strNameSpace + ' id="dlt_org" baseNode="list" repeatNode="map">';        
    strOrgTarget += '<w2:columnInfo>'
    strOrgTarget += '<w2:column id="label" name="label" dataType="text"></w2:column>'
    strOrgTarget += '<w2:column id="quarter" name="quarter" dataType="text"></w2:column>'
    strOrgTarget += '<w2:column id="type1" name="2025" dataType="text"></w2:column>'
    strOrgTarget += '<w2:column id="type2" name="2026" dataType="text"></w2:column>'
    strOrgTarget += '<w2:column id="type3" name="2027" dataType="text"></w2:column>'
    strOrgTarget += '</w2:columnInfo>'
    strOrgTarget += '<w2:data use="true">'
    strOrgTarget += '<w2:row>'
    strOrgTarget += '<label><![CDATA[label1]]></label>'
    strOrgTarget += '<quarter><![CDATA[Q1]]></quarter>'
    strOrgTarget += '<type1><![CDATA[11500]]></type1>'
    strOrgTarget += '<type2><![CDATA[28110]]></type2>'
    strOrgTarget += '<type3><![CDATA[23990]]></type3>'
    strOrgTarget += '</w2:row>'
    strOrgTarget += '<w2:row>'
    strOrgTarget += '<label><![CDATA[label2]]></label>'
    strOrgTarget += '<quarter><![CDATA[Q2]]></quarter>'
    strOrgTarget += '<type1><![CDATA[1500]]></type1>'
    strOrgTarget += '<type2><![CDATA[10600]]></type2>'
    strOrgTarget += '<type3><![CDATA[10000]]></type3>'
    strOrgTarget += '</w2:row>'
    strOrgTarget += '<w2:row>'
    strOrgTarget += '<label><![CDATA[label3]]></label>'
    strOrgTarget += '<quarter><![CDATA[Q3]]></quarter>'
    strOrgTarget += '<type1><![CDATA[27400]]></type1>'
    strOrgTarget += '<type2><![CDATA[31800]]></type2>'
    strOrgTarget += '<type3><![CDATA[42800]]></type3>'
    strOrgTarget += '</w2:row>'
    strOrgTarget += '<w2:row>'
    strOrgTarget += '<label><![CDATA[label4]]></label>'
    strOrgTarget += '<quarter><![CDATA[Q4]]></quarter>'
    strOrgTarget += '<type1><![CDATA[27400]]></type1>'
    strOrgTarget += '<type2><![CDATA[22900]]></type2>'
    strOrgTarget += '<type3><![CDATA[20800]]></type3>'
    strOrgTarget += '</w2:row>'
    strOrgTarget += '</w2:data>'
    strOrgTarget += '</w2:dataList>'   

    $p.data.create(strOrgTarget);

    strTarget += '<w2:linkedDataList ' + strNameSpace + ' id="target1" bind="dlt_org">'
    strTarget += '<w2:condition type="filter"><![CDATA[]]></w2:condition>'
    strTarget += '<w2:condition type="sort"><![CDATA[]]></w2:condition>'
    strTarget += '</w2:linkedDataList>'

    $p.data.create(strTarget);


    // // FusionChart 생성
    // strFusionChart += '<w2:fusionchart ' + strNameSpace + ' seriesType="advanced" drawType="javascript" runflashAt="IE6,IE7,IE8" chartType="MSColumn2D"	style="width:600px; height:200px;" id="" ref="data:target1" labelNode="quarter" seriesColumns="[[\'type1\',\'type2\',\'type3\']]" valueNode="value"></w2:fusionchart>';   

    // // gridView 생성
    // scwin["fusionChart1"] = await $p.dynamicCreate(
    //     "fusionChart1",
    //     "fusionchart",
    //     strFusionChart,
    //     grp_comp
    // );    

    // scwin.btn_getFusionChartData_onclick();
}   



scwin.btn_getFusionChartData_onclick = function (e) {
    let chartType = par_chartType.getText();
    let labelNode = par_labelNode.getText();
    let seriesColumns = par_seriesColumns.getText();

    let jsonObject = target1.getFusionChartData(chartType, labelNode, seriesColumns);    
    let jsonString = JSON.stringify(jsonObject);   

	wf_body_bottom.getObj("scwin").setReturnValue("getFusionChartData: " + jsonString);
};
